insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('5552caea-97d0-5d98-9cb1-c77f0eb422e7', 'Botany', 'Photosynthesis in Higher Plants', 'Medium', 'The reaction centre chlorophyll a of Photosystem II absorbs light maximally at:', '["700 nm","680 nm","640 nm","450 nm"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('5552caea-97d0-5d98-9cb1-c77f0eb422e7', 1, 'Photosystem II has a reaction centre chlorophyll a that absorbs best at 680 nm, so it is called P680. It sits at the start of the light reaction and is linked to the splitting of water.', '["700 nm is P700, the reaction centre of Photosystem I.","","640 nm is close to the red peak of chlorophyll b, not a reaction centre.","450 nm is a blue-region peak that several pigments share. It does not name a reaction centre."]'::jsonb, '{"concept":"The number in P680 and P700 is the wavelength in nm that the reaction centre absorbs best.","mistake":"Mixing up which photosystem is which. PS II is 680, PS I is 700."}'::jsonb, 'Class 11 · Photosynthesis in Higher Plants', 'PS II uses P680 and starts the Z-scheme by splitting water.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('5552caea-97d0-5d98-9cb1-c77f0eb422e7', 1, 'Photosystems are named P680 and P700. What does the number stand for?', array['wavelength', 'nm', 'absorb', 'light']::text[], 'The number is a measurement of light.', 'Yes. It is the wavelength in nm that the reaction centre absorbs best.', 'the wavelength of light it absorbs', array['The wavelength of light it absorbs best', 'The number of pigment molecules', 'The order of discovery', 'The charge of the reaction centre']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('5552caea-97d0-5d98-9cb1-c77f0eb422e7', 2, 'Which photosystem acts first in the Z-scheme and is linked to water splitting?', array['ii', 'two', '2', '680', 'water']::text[], 'The names are historical, not in order of action. Think of where water is split.', 'PS II (P680) acts first and is linked to water splitting.', 'PS II', array['PS II', 'PS I', 'Both at the same moment', 'Neither, the dark reaction does']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('cd8fed26-cd00-5ec3-983d-90f3c76ac12c', 'Botany', 'Photosynthesis in Higher Plants', 'Medium', 'In C4 plants, the primary acceptor of CO2 in the mesophyll cells is:', '["RuBP","Phosphoenolpyruvate (PEP)","Oxaloacetic acid","3-phosphoglyceric acid"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('cd8fed26-cd00-5ec3-983d-90f3c76ac12c', 1, 'In the mesophyll of C4 plants, PEP carboxylase fixes CO2 onto the 3-carbon molecule PEP to form 4-carbon oxaloacetic acid. The Calvin cycle then runs in the bundle sheath cells.', '["RuBP is the CO2 acceptor of the Calvin cycle, which runs in the bundle sheath here.","","Oxaloacetic acid is the first stable product, not the acceptor.","3-PGA is the first stable product of the C3 pathway."]'::jsonb, '{"concept":"C4: PEP (3C) + CO2 gives OAA (4C) in the mesophyll, then Calvin cycle in the bundle sheath.","mistake":"Calling OAA the acceptor. It is the product."}'::jsonb, 'Class 11 · Photosynthesis in Higher Plants', 'C4 plants split carbon fixation across two cell types.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('cd8fed26-cd00-5ec3-983d-90f3c76ac12c', 1, 'In a C4 leaf, which cells run the Calvin cycle: mesophyll or bundle sheath?', array['bundle', 'sheath']::text[], 'Kranz anatomy puts the Calvin cycle in the inner ring of cells.', 'Correct, the bundle sheath cells.', 'bundle sheath', array['Bundle sheath cells', 'Mesophyll cells', 'Guard cells', 'Epidermal cells']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('cd8fed26-cd00-5ec3-983d-90f3c76ac12c', 2, 'So which 3-carbon molecule in the mesophyll picks up CO2 first and makes a 4-carbon acid?', array['pep', 'phosphoenol']::text[], 'The enzyme is PEP carboxylase. Name its substrate.', 'That is PEP, phosphoenolpyruvate.', 'PEP', array['PEP', 'RuBP', 'Pyruvic acid', 'Glucose']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('56cbb07c-68ed-57cd-a147-45cc3e30f0c1', 'Botany', 'Cell Cycle and Cell Division', 'Easy', 'DNA replication in the cell cycle takes place during:', '["G1 phase","S phase","G2 phase","M phase"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('56cbb07c-68ed-57cd-a147-45cc3e30f0c1', 1, 'DNA is replicated in the S (synthesis) phase of interphase. The DNA content doubles from 2C to 4C, but the chromosome number stays the same.', '["G1 is a growth phase with no DNA synthesis.","","G2 is preparation for mitosis. DNA is already doubled.","M phase is mitosis, which divides the already replicated DNA."]'::jsonb, '{"concept":"S phase: DNA content 2C to 4C. Chromosome number unchanged.","mistake":"Thinking chromosome number doubles in S phase."}'::jsonb, 'Class 11 · Cell Cycle and Cell Division', 'Interphase is G1, S and G2. DNA doubles in S.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('56cbb07c-68ed-57cd-a147-45cc3e30f0c1', 1, 'One phase of interphase is named for synthesis. Which letter is it?', array['s phase', 's-phase', 'synthesis']::text[], 'Write the phase as "S phase" if you are sure.', 'Yes, the S (synthesis) phase.', 'S phase', array['S phase', 'G1 phase', 'M phase', 'G0 phase']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('56cbb07c-68ed-57cd-a147-45cc3e30f0c1', 2, 'At G2, does the cell have half, the same or double the DNA of G1?', array['double', 'twice', '4c', 'two times']::text[], 'DNA was just copied in the previous phase.', 'Double: 2C becomes 4C.', 'double', array['Double', 'Half', 'The same', 'Four times']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('dd71947b-7f84-544e-80ad-c7bb828bd98f', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Medium', 'The primary endosperm nucleus (PEN) in angiosperms is:', '["Haploid","Diploid","Triploid","Tetraploid"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('dd71947b-7f84-544e-80ad-c7bb828bd98f', 2, 'In double fertilisation one male gamete fuses with the egg (zygote) and the other fuses with the two polar nuclei in the central cell. Haploid + haploid + haploid makes the triploid PEN, which grows into the endosperm.', '["Haploid is a gamete or a single polar nucleus.","Diploid is the zygote.","","Tetraploid does not arise in normal double fertilisation."]'::jsonb, '{"concept":"Syngamy gives a diploid zygote. Triple fusion gives a triploid PEN.","mistake":"Forgetting that the central cell has two polar nuclei."}'::jsonb, 'Class 12 · Sexual Reproduction in Flowering Plants', 'Double fertilisation: syngamy plus triple fusion.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('dd71947b-7f84-544e-80ad-c7bb828bd98f', 1, 'In double fertilisation one male gamete fuses with the egg. What does the other fuse with?', array['polar', 'central cell']::text[], 'It is in the large central cell of the embryo sac.', 'The two polar nuclei of the central cell.', 'the two polar nuclei', array['The two polar nuclei', 'The antipodals', 'The synergids', 'The egg again']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('dd71947b-7f84-544e-80ad-c7bb828bd98f', 2, 'Each gamete and each polar nucleus is n. How many sets of chromosomes after that fusion?', array['3', '3n', 'three', 'triploid']::text[], 'One male gamete plus two polar nuclei.', '3n, so triploid.', '3n', array['3n', '2n', 'n', '4n']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('0a41e82e-ca8b-5147-a27d-fe031dcbf575', 'Botany', 'Plant Growth and Development', 'Easy', 'Bolting in rosette plants such as cabbage is induced by:', '["Auxin","Gibberellin","Cytokinin","Abscisic acid"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('0a41e82e-ca8b-5147-a27d-fe031dcbf575', 1, 'Bolting is the sudden elongation of the flowering stalk in rosette plants. Gibberellins promote internode elongation, so spraying them induces bolting.', '["Auxin mainly causes apical dominance and cell elongation, not bolting.","","Cytokinin promotes cell division and delays senescence.","ABA is a growth inhibitor linked to dormancy and stress."]'::jsonb, '{"concept":"Gibberellins: internode elongation, bolting, seed germination.","mistake":"Choosing auxin because it is linked to elongation."}'::jsonb, 'Class 11 · Plant Growth and Development', 'Gibberellin spray makes a rosette plant bolt.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('0a41e82e-ca8b-5147-a27d-fe031dcbf575', 1, 'Bolting is the rapid elongation of which plant part?', array['stem', 'internode', 'stalk', 'elong']::text[], 'Rosette plants have very short internodes.', 'Right, the stem internodes and flowering stalk.', 'the stem', array['Stem internodes', 'Roots', 'Leaves', 'Seeds']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('0a41e82e-ca8b-5147-a27d-fe031dcbf575', 2, 'Which hormone is best known for promoting stem elongation in dwarf plants?', array['gibberell', 'ga3']::text[], 'It was first found in a fungus that made rice seedlings grow too tall.', 'Gibberellin.', 'gibberellin', array['Gibberellin', 'Auxin', 'Cytokinin', 'Abscisic acid']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('2b89e523-249f-58c3-97ac-6ee8546b5755', 'Zoology', 'Human Reproduction', 'Easy', 'In the human male, sperms are stored and finish maturing in the:', '["Seminiferous tubules","Epididymis","Vas deferens","Prostate gland"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('2b89e523-249f-58c3-97ac-6ee8546b5755', 1, 'Sperms are made in the seminiferous tubules and move to the epididymis, where they gain motility and the ability to fertilise, and are stored.', '["Seminiferous tubules are the site of sperm formation, not storage.","","The vas deferens carries sperms toward the urethra.","The prostate adds secretion to the seminal plasma."]'::jsonb, '{"concept":"Formation: seminiferous tubules. Maturation and storage: epididymis.","mistake":"Choosing the site of formation."}'::jsonb, 'Class 12 · Human Reproduction', 'The sperm path: testis, epididymis, vas deferens, urethra.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('2b89e523-249f-58c3-97ac-6ee8546b5755', 1, 'Where are sperms produced?', array['seminiferous', 'testis', 'testes']::text[], 'Inside the testis, in coiled tubules.', 'The seminiferous tubules.', 'seminiferous tubules', array['Seminiferous tubules', 'Epididymis', 'Prostate', 'Vas deferens']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('2b89e523-249f-58c3-97ac-6ee8546b5755', 2, 'After that, a long coiled tube on the testis surface gives them motility. What is it called?', array['epididym']::text[], 'It starts with "epi", meaning on top of the testis.', 'The epididymis.', 'epididymis', array['Epididymis', 'Seminal vesicle', 'Urethra', 'Prostate']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('1f8b128e-dd3a-5717-8b69-7b92330cd087', 'Zoology', 'Human Reproduction', 'Medium', 'Ovulation in the human menstrual cycle is triggered by a surge of:', '["FSH","LH","Progesterone","Oestrogen"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('1f8b128e-dd3a-5717-8b69-7b92330cd087', 1, 'A mid-cycle surge of LH, the LH surge, causes the Graafian follicle to rupture and release the ovum. Rising oestrogen from the follicle triggers the surge by positive feedback.', '["FSH stimulates follicle growth earlier in the cycle.","","Progesterone is made by the corpus luteum after ovulation.","Oestrogen triggers the surge but does not itself cause the follicle to rupture."]'::jsonb, '{"concept":"High oestrogen leads to an LH surge, which leads to ovulation around day 14.","mistake":"Picking oestrogen because it comes first in the chain."}'::jsonb, 'Class 12 · Human Reproduction', 'The LH surge is the immediate trigger for ovulation.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('1f8b128e-dd3a-5717-8b69-7b92330cd087', 1, 'Which anterior pituitary hormone surges at mid-cycle, around day 14?', array['lh', 'luteinizing', 'luteinising']::text[], 'Its name starts with L and it later helps form the corpus luteum.', 'LH, luteinising hormone.', 'LH', array['LH', 'FSH', 'Prolactin', 'Progesterone']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('1f8b128e-dd3a-5717-8b69-7b92330cd087', 2, 'Which rising hormone from the growing follicle gives positive feedback to cause that surge?', array['oestrogen', 'estrogen', 'estradiol']::text[], 'It is made by the granulosa cells of the follicle.', 'Oestrogen. It drives the surge, and LH does the rupturing.', 'oestrogen', array['Oestrogen', 'Progesterone', 'Testosterone', 'Oxytocin']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('a6aaa655-7416-58d1-a3eb-392d6edd5bac', 'Zoology', 'Principles of Inheritance and Variation', 'Medium', 'A test cross of a dihybrid (AaBb × aabb) gives the phenotypic ratio:', '["9:3:3:1","1:1:1:1","3:1","1:2:1"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('a6aaa655-7416-58d1-a3eb-392d6edd5bac', 1, 'AaBb makes four gamete types (AB, Ab, aB, ab) in equal numbers by independent assortment. The recessive parent only gives ab, so the offspring show 1:1:1:1.', '["9:3:3:1 is the F2 ratio of a dihybrid cross (AaBb × AaBb).","","3:1 is a monohybrid F2 phenotypic ratio.","1:2:1 is the monohybrid genotypic ratio."]'::jsonb, '{"concept":"Test cross ratio reflects the gamete ratio of the tested parent.","mistake":"Using the F2 ratio 9:3:3:1."}'::jsonb, 'Class 12 · Principles of Inheritance and Variation', 'The recessive parent reveals the gametes of the other parent.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('a6aaa655-7416-58d1-a3eb-392d6edd5bac', 1, 'What gamete types does AaBb make, assuming independent assortment?', array['four', '4', 'ab, ab, ab']::text[], 'Pick one allele of each gene in every combination.', 'AB, Ab, aB and ab.', 'AB, Ab, aB, ab', array['All four: AB, Ab, aB, ab', 'Two types: AB and ab', 'Two types: Ab and aB', 'One type: AB']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('a6aaa655-7416-58d1-a3eb-392d6edd5bac', 2, 'The aabb parent makes only ab. What does that do to the ratio of offspring?', array['equal', '1:1', 'same', 'each']::text[], 'Each offspring type matches one gamete of the first parent.', 'The offspring ratio copies the gamete ratio, so 1:1:1:1.', 'equal for all four', array['Equal numbers of all four types', '3 to 1', '9 : 3 : 3 : 1', 'Only one type']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('fd3e2760-c268-55ef-9477-ce36b2eed1ca', 'Zoology', 'Excretory Products and their Elimination', 'Medium', 'Which part of the loop of Henle is impermeable to water?', '["Descending limb","Ascending limb","Proximal convoluted tubule","Collecting duct"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('fd3e2760-c268-55ef-9477-ce36b2eed1ca', 1, 'The ascending limb is impermeable to water but lets electrolytes move out, so the filtrate gets diluted as it rises. The descending limb is permeable to water, which makes the filtrate concentrated.', '["The descending limb is permeable to water.","","The PCT reabsorbs most of the water and solutes.","The collecting duct is permeable to water, regulated by ADH."]'::jsonb, '{"concept":"Descending limb: water out, filtrate concentrates. Ascending limb: salts out, no water.","mistake":"Swapping the two limbs."}'::jsonb, 'Class 11 · Excretory Products and their Elimination', 'The two limbs create the medullary gradient.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('fd3e2760-c268-55ef-9477-ce36b2eed1ca', 1, 'As the filtrate goes down the descending limb, does water leave or enter?', array['leave', 'out', 'concentrat']::text[], 'The medulla is very concentrated.', 'Water leaves, so the filtrate gets concentrated.', 'water leaves', array['Water leaves, filtrate concentrates', 'Water enters, filtrate dilutes', 'Nothing moves', 'Only urea is removed']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('fd3e2760-c268-55ef-9477-ce36b2eed1ca', 2, 'In the ascending limb, salts move out. Can water follow them?', array['no', 'not', 'impermeable', 'cannot']::text[], 'Think about why the filtrate becomes dilute here.', 'No. The ascending limb is impermeable to water.', 'no, water cannot follow', array['No, it is impermeable to water', 'Yes, water follows freely', 'Only when ADH is high', 'Only at night']::text[]) on conflict (question_id, position) do nothing;
insert into public.questions (id, subject, chapter, difficulty, text, options, status) values ('47479b7d-6510-5a2c-b8ac-da5ef86b3593', 'Zoology', 'Body Fluids and Circulation', 'Easy', 'The pacemaker of the human heart is the:', '["AV node","SA node","Bundle of His","Purkinje fibres"]'::jsonb, 'published') on conflict (id) do nothing;
insert into public.question_secrets (question_id, correct, explanation, why_wrong, recap, ncert, caption) values ('47479b7d-6510-5a2c-b8ac-da5ef86b3593', 1, 'The sinoatrial (SA) node in the right atrium generates the highest rate of spontaneous impulses, so it sets the heart rate. The AV node, bundle of His and Purkinje fibres conduct the impulse to the ventricles.', '["The AV node delays and relays the impulse. It is a backup pacemaker at a slower rate.","","The bundle of His conducts to the ventricles.","Purkinje fibres spread the impulse through the ventricular muscle."]'::jsonb, '{"concept":"The tissue that fires fastest sets the rhythm. In the heart that is the SA node.","mistake":"Choosing the AV node because it sits in the middle of the conduction path."}'::jsonb, 'Class 11 · Body Fluids and Circulation', 'SA node, AV node, bundle of His, Purkinje fibres.') on conflict (question_id) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('47479b7d-6510-5a2c-b8ac-da5ef86b3593', 1, 'In which chamber of the heart is the SA node located?', array['right atrium', 'upper right']::text[], 'It is in the upper wall of one atrium.', 'The right atrium.', 'right atrium', array['Right atrium', 'Left ventricle', 'Interventricular septum', 'Left atrium']::text[]) on conflict (question_id, position) do nothing;
insert into public.socratic_steps (question_id, position, ask, keys, hint, good, sample, choices) values ('47479b7d-6510-5a2c-b8ac-da5ef86b3593', 2, 'Why does the node with the fastest spontaneous rate end up in charge of the heartbeat?', array['fast', 'highest', 'rate', 'first']::text[], 'Whichever part fires first sets the pace for the others.', 'It fires first and fastest, so the others follow.', 'it fires fastest', array['It fires fastest, so the others follow', 'It is the largest node', 'It is closest to the aorta', 'It is controlled by the lungs']::text[]) on conflict (question_id, position) do nothing;
